package com.personal.dashboard;

import android.app.*;import android.os.Bundle;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.view.*;import android.widget.*;import android.text.InputType;import java.text.*;import java.util.*;

public class MainActivity extends Activity {
 static final int BG=0xff020906,PANEL=0xff05140d,PANEL2=0xff071b12,GREEN=0xff00f59b,TEXT=0xffbbffdd,MUTED=0xff5b9d7c,RED=0xffff5f70; DB db;LinearLayout root,content;String page="Início";
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} GradientDrawable shape(int color,int stroke){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(12));d.setStroke(dp(1),stroke);return d;}
 TextView tx(String s,int z,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setTextColor(color);return t;} LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);return l;} LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(0);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
 void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);db=new DB(this);home();}
 void base(String title){root=col();root.setBackgroundColor(BG);setContentView(root);LinearLayout h=col();h.setPadding(dp(18),dp(10),dp(18),dp(8));TextView a=tx("◉  "+title.toUpperCase(Locale.ROOT),21,GREEN);a.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);h.addView(a);h.addView(tx("PLANEJE. REGISTRE. EVOLUA.",10,MUTED));root.addView(h);ScrollView sc=new ScrollView(this);content=col();content.setPadding(dp(12),dp(8),dp(12),dp(16));sc.addView(content);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));nav();}
 void nav(){LinearLayout n=row();n.setBackgroundColor(PANEL);String[] a={"⌂\nInício","▥\nEstatísticas","＋\nRegistro","♜\nMissões","⚙\nConfig."};for(String s:a){String name=s.substring(s.indexOf('\n')+1);TextView t=tx(s,10,page.equals(name)?GREEN:MUTED);t.setGravity(17);n.addView(t,new LinearLayout.LayoutParams(0,dp(48),1));t.setOnClickListener(v->{switch(name){case "Registro":recordMenu();break;case "Missões":missions();break;case "Estatísticas":stats();break;case "Config.":settings();break;default:home();}});}root.addView(n);}
 LinearLayout card(String title){LinearLayout c=col();c.setPadding(dp(11),dp(11),dp(11),dp(11));c.setBackground(shape(PANEL,0xff006941));TextView t=tx("▣  "+title.toUpperCase(Locale.ROOT),11,GREEN);t.setTypeface(null,1);c.addView(t);return c;}void section(View v){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(9);content.addView(v,p);}Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextColor(BG);b.setTextSize(12);b.setAllCaps(false);b.setBackground(shape(GREEN,GREEN));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(46));p.topMargin=dp(7);b.setLayoutParams(p);return b;}String money(double x){return String.format(new Locale("pt","BR"),"R$ %,.2f",x);}void toast(String s){Toast.makeText(this,s,0).show();}
 void home(){page="Início";base("Painel");LinearLayout r=row();LinearLayout f=card("Saldo total");f.addView(tx(money(db.balance()),23,TEXT));f.addView(tx(db.balance()>=0?"▲ POSITIVO":"▼ NEGATIVO",10,GREEN));f.addView(new MiniChart(this,db.weekBalances()));LinearLayout t=card("Saldo de hoje");t.addView(tx(money(db.todayNet()),23,TEXT));t.addView(tx("ENTRADAS − SAÍDAS",10,GREEN));t.addView(new MiniChart(this,db.weekDaily()));LinearLayout.LayoutParams half=new LinearLayout.LayoutParams(0,-2,1);half.rightMargin=dp(4);r.addView(f,half);LinearLayout.LayoutParams half2=new LinearLayout.LayoutParams(0,-2,1);half2.leftMargin=dp(4);r.addView(t,half2);section(r);
 LinearLayout rr=row();LinearLayout w=card("Desempenho");w.addView(tx("FLEXÕES",10,MUTED));int lp=db.last("push"),bp=db.best("push"),pp=db.prev("push");w.addView(tx(lp+"",29,TEXT));w.addView(tx("Recorde: "+bp+"  "+mark(lp,bp),10,GREEN));w.addView(tx("vs. anterior: "+cmp(lp,pp),10,cmpColor(lp,pp)));View line=new View(this);line.setBackgroundColor(0xff16442f);LinearLayout.LayoutParams ll=new LinearLayout.LayoutParams(-1,dp(1));ll.topMargin=dp(8);ll.bottomMargin=dp(8);w.addView(line,ll);w.addView(tx("BARRAS",10,MUTED));int lb=db.last("pull"),bb=db.best("pull"),pb=db.prev("pull");w.addView(tx(lb+"",29,TEXT));w.addView(tx("Recorde: "+bb+"  "+mark(lb,bb),10,GREEN));w.addView(tx("vs. anterior: "+cmp(lb,pb),10,cmpColor(lb,pb)));LinearLayout e=card("Evolução financeira");e.addView(tx("ÚLTIMOS 7 DIAS",10,MUTED));e.addView(new StockChart(this,db.weekDaily()));e.addView(tx("Variação: "+money(db.weekNet()),10,GREEN));LinearLayout.LayoutParams x=new LinearLayout.LayoutParams(0,-2,1);x.rightMargin=dp(4);rr.addView(w,x);LinearLayout.LayoutParams y=new LinearLayout.LayoutParams(0,-2,1);y.leftMargin=dp(4);rr.addView(e,y);section(rr);
 LinearLayout m=card("Missões");m.addView(tx(db.missionCount()+" MISSÕES ATIVAS",12,TEXT));m.addView(tx(db.missionPreview(),11,MUTED));Button mb=btn("＋  GERENCIAR MISSÕES");mb.setOnClickListener(v->missions());m.addView(mb);section(m);
 LinearLayout q=card("Registro rápido");Button a=btn("＋  REGISTRAR TREINO");a.setOnClickListener(v->workoutDialog());q.addView(a);Button b=btn("＋  REGISTRAR FINANÇAS");b.setOnClickListener(v->financeDialog(null));q.addView(b);section(q);}
 String mark(int a,int b){return a>b?"▲ NOVO RECORDE":a==b&&a>0?"＝ RECORDE":"▼ ABAIXO";}String cmp(int a,int b){return b<0?"primeiro treino":a>b?"▲ Melhorou +"+(a-b):a<b?"▼ Piorou -"+(b-a):"＝ Igual";}int cmpColor(int a,int b){return b<0?MUTED:a>=b?GREEN:RED;}
 void recordMenu(){new AlertDialog.Builder(this).setTitle("Novo registro").setItems(new String[]{"Entrada financeira","Saída financeira","Treino"},(d,w)->{if(w==2)workoutDialog();else financeDialog(w==0);}).show();}
 void financeDialog(Boolean isIn){LinearLayout box=col();box.setPadding(dp(8),0,dp(8),0);EditText val=new EditText(this);val.setHint("Valor (ex.: 45,90)");val.setInputType(8194);box.addView(val);EditText desc=new EditText(this);desc.setHint("Descrição");box.addView(desc);EditText date=new EditText(this);date.setHint("Data (AAAA-MM-DD)");date.setText(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));box.addView(date);RadioGroup rg=new RadioGroup(this);rg.setOrientation(0);RadioButton in=new RadioButton(this);in.setId(1);in.setText("Entrada");RadioButton out=new RadioButton(this);out.setId(2);out.setText("Saída");rg.addView(in);rg.addView(out);rg.check(isIn==null||isIn?1:2);box.addView(rg);new AlertDialog.Builder(this).setTitle("Registro financeiro").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",(d,w)->{try{double a=Double.parseDouble(val.getText().toString().replace(",","."));if(a<=0)throw new Exception();db.addFinance(a,rg.getCheckedRadioButtonId()==1,desc.getText().toString(),date.getText().toString().trim());home();}catch(Exception ex){toast("Digite um valor válido.");}}).show();}
 void workoutDialog(){LinearLayout box=col();EditText p=new EditText(this);p.setHint("Flexões");p.setInputType(2);box.addView(p);EditText b=new EditText(this);b.setHint("Barras");b.setInputType(2);box.addView(b);new AlertDialog.Builder(this).setTitle("Registrar treino").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Salvar",(d,w)->{try{int a=Integer.parseInt(p.getText().toString().isEmpty()?"0":p.getText().toString()),z=Integer.parseInt(b.getText().toString().isEmpty()?"0":b.getText().toString());if(a<0||z<0||a+z==0)throw new Exception();db.addWorkout(a,z);home();}catch(Exception e){toast("Registre pelo menos um exercício.");}}).show();}
 void missions(){page="Missões";base("Missões");LinearLayout top=card("Central de missões");top.addView(tx("Crie uma missão e divida em subquests.",11,MUTED));Button create=btn("＋  CRIAR MISSÃO");create.setOnClickListener(v->missionDialog());top.addView(create);section(top);Cursor c=db.missions();while(c.moveToNext()){int id=c.getInt(0);LinearLayout item=card(c.getString(1));Cursor tasks=db.tasks(id);int total=0,done=0;while(tasks.moveToNext()){total++;if(tasks.getInt(2)==1)done++;}tasks.close();item.addView(tx(done+" / "+total+" concluídas",10,GREEN));ProgressBar pb=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);pb.setMax(Math.max(1,total));pb.setProgress(done);item.addView(pb);Cursor q=db.tasks(id);while(q.moveToNext()){int tid=q.getInt(0);CheckBox cb=new CheckBox(this);cb.setText(q.getString(1));cb.setTextColor(TEXT);cb.setTextSize(12);cb.setChecked(q.getInt(2)==1);cb.setOnCheckedChangeListener((v,checked)->{db.toggle(tid,checked);missions();});item.addView(cb);}q.close();Button add=btn("＋ ADICIONAR SUBQUEST");add.setOnClickListener(v->subDialog(id));item.addView(add);Button del=btn("EXCLUIR MISSÃO");del.setTextColor(RED);del.setBackground(shape(PANEL2,RED));del.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("Excluir missão e etapas?").setNegativeButton("Cancelar",null).setPositiveButton("Excluir",(a,b)->{db.deleteMission(id);missions();}).show());item.addView(del);section(item);}c.close();}
 void missionDialog(){EditText e=new EditText(this);e.setHint("Nome da missão");new AlertDialog.Builder(this).setTitle("Criar missão").setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Criar",(d,w)->{if(e.getText().length()>0){db.addMission(e.getText().toString());missions();}}).show();}void subDialog(int id){EditText e=new EditText(this);e.setHint("Nome da subquest");new AlertDialog.Builder(this).setTitle("Nova subquest").setView(e).setNegativeButton("Cancelar",null).setPositiveButton("Adicionar",(d,w)->{if(e.getText().length()>0){db.addTask(id,e.getText().toString());missions();}}).show();}
 void stats(){page="Estatísticas";base("Estatísticas");LinearLayout c=card("Gráfico semanal");c.addView(new StockChart(this,db.weekDaily()));section(c);LinearLayout w=card("Histórico de treinos");w.addView(tx(db.workoutHistory(),11,TEXT));section(w);LinearLayout f=card("Resumo financeiro");f.addView(tx("Entradas: "+money(db.sum(true)),12,GREEN));f.addView(tx("Saídas: "+money(db.sum(false)),12,RED));f.addView(tx("Saldo: "+money(db.balance()),20,TEXT));section(f);LinearLayout history=card("Movimentações recentes");history.addView(tx(db.financeHistory(),11,TEXT));section(history);}
 void settings(){page="Config.";base("Configurações");LinearLayout c=card("Armazenamento local");c.addView(tx("Os dados ficam salvos neste aparelho. Não exige conta nem conexão.",11,MUTED));Button b=btn("APAGAR TODOS OS DADOS");b.setTextColor(RED);b.setBackground(shape(PANEL2,RED));b.setOnClickListener(v->new AlertDialog.Builder(this).setMessage("Apagar todos os registros? Não é possível desfazer.").setNegativeButton("Cancelar",null).setPositiveButton("Apagar",(d,w)->{db.reset();home();}).show());c.addView(b);section(c);}
 class MiniChart extends View{Paint p=new Paint(3);double[] a;MiniChart(Context c,double[] v){super(c);a=v;setMinimumHeight(dp(36));}protected void onDraw(Canvas c){float w=getWidth(),h=dp(34);p.setColor(0xff16442f);p.setStrokeWidth(dp(1));for(int i=1;i<4;i++)c.drawLine(0,h*i/4,w,h*i/4,p);drawLine(c,w,h);setMinimumHeight(dp(35));}void drawLine(Canvas c,float w,float h){if(a.length==0)return;double min=Arrays.stream(a).min().orElse(0),max=Arrays.stream(a).max().orElse(1);if(max==min)max=min+1;p.setColor(GREEN);p.setStrokeWidth(dp(2));Path path=new Path();for(int i=0;i<a.length;i++){float x=dp(5)+(w-dp(10))*i/Math.max(1,a.length-1),y=(float)(h-dp(6)-(a[i]-min)/(max-min)*(h-dp(12)));if(i==0)path.moveTo(x,y);else path.lineTo(x,y);c.drawCircle(x,y,dp(2.5f),p);}c.drawPath(path,p);}}
 class StockChart extends View{Paint p=new Paint(3);double[] a;StockChart(Context c,double[] v){super(c);a=v;setMinimumHeight(dp(130));}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();p.setColor(0xff16442f);p.setStrokeWidth(dp(1));for(int i=1;i<4;i++)c.drawLine(0,h*i/4,w,h*i/4,p);if(a.length==0)return;double min=Arrays.stream(a).min().orElse(0),max=Arrays.stream(a).max().orElse(1);if(max==min)max=min+1;p.setColor(GREEN);p.setStrokeWidth(dp(2));Path path=new Path();for(int i=0;i<a.length;i++){float x=dp(8)+(w-dp(16))*i/Math.max(1,a.length-1),y=(float)(h-dp(10)-(a[i]-min)/(max-min)*(h-dp(20)));if(i==0)path.moveTo(x,y);else path.lineTo(x,y);c.drawCircle(x,y,dp(3),p);}c.drawPath(path,p);}}
 class DB extends SQLiteOpenHelper{DB(Context c){super(c,"personal.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE finance(id INTEGER PRIMARY KEY,amount REAL,income INTEGER,description TEXT,date TEXT)");d.execSQL("CREATE TABLE workouts(id INTEGER PRIMARY KEY,push INTEGER,pull INTEGER,date TEXT)");d.execSQL("CREATE TABLE missions(id INTEGER PRIMARY KEY,name TEXT)");d.execSQL("CREATE TABLE tasks(id INTEGER PRIMARY KEY,mission_id INTEGER,name TEXT,done INTEGER DEFAULT 0)");}public void onUpgrade(SQLiteDatabase d,int a,int b){}String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());}
 void addFinance(double a,boolean in,String s,String date){ContentValues v=new ContentValues();v.put("amount",a);v.put("income",in?1:0);v.put("description",s);v.put("date",date.isEmpty()?today():date);getWritableDatabase().insert("finance",null,v);}double sum(boolean in){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(amount),0) FROM finance WHERE income=?",new String[]{in?"1":"0"});c.moveToFirst();double x=c.getDouble(0);c.close();return x;}double balance(){return sum(true)-sum(false);}double todayNet(){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(CASE WHEN income=1 THEN amount ELSE -amount END),0) FROM finance WHERE date=?",new String[]{today()});c.moveToFirst();double x=c.getDouble(0);c.close();return x;}double[] weekDaily(){double[] a=new double[7];Calendar now=Calendar.getInstance();for(int i=6;i>=0;i--){Calendar day=(Calendar)now.clone();day.add(5,-i);String date=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(day.getTime());Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(SUM(CASE WHEN income=1 THEN amount ELSE -amount END),0) FROM finance WHERE date=?",new String[]{date});c.moveToFirst();a[6-i]=c.getDouble(0);c.close();}return a;}double[] weekBalances(){double[] a=weekDaily();double n=balance();for(double v:a)n-=v;for(int i=0;i<7;i++){n+=a[i];a[i]=n;}return a;}double weekNet(){double n=0;for(double v:weekDaily())n+=v;return n;}
 void addWorkout(int p,int b){ContentValues v=new ContentValues();v.put("push",p);v.put("pull",b);v.put("date",today());getWritableDatabase().insert("workouts",null,v);}int last(String f){Cursor c=getReadableDatabase().rawQuery("SELECT "+f+" FROM workouts ORDER BY id DESC LIMIT 1",null);int n=c.moveToFirst()?c.getInt(0):0;c.close();return n;}int best(String f){Cursor c=getReadableDatabase().rawQuery("SELECT COALESCE(MAX("+f+"),0) FROM workouts",null);c.moveToFirst();int n=c.getInt(0);c.close();return n;}int prev(String f){Cursor c=getReadableDatabase().rawQuery("SELECT "+f+" FROM workouts ORDER BY id DESC LIMIT 1 OFFSET 1",null);int n=c.moveToFirst()?c.getInt(0):-1;c.close();return n;}
 void addMission(String s){ContentValues v=new ContentValues();v.put("name",s);getWritableDatabase().insert("missions",null,v);}Cursor missions(){return getReadableDatabase().rawQuery("SELECT id,name FROM missions ORDER BY id DESC",null);}int missionCount(){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM missions",null);c.moveToFirst();int n=c.getInt(0);c.close();return n;}String missionPreview(){Cursor c=missions();String s="Nenhuma missão criada.";if(c.moveToFirst())s=c.getString(1);c.close();return s;}void addTask(int id,String s){ContentValues v=new ContentValues();v.put("mission_id",id);v.put("name",s);getWritableDatabase().insert("tasks",null,v);}Cursor tasks(int id){return getReadableDatabase().rawQuery("SELECT id,name,done FROM tasks WHERE mission_id=? ORDER BY id",new String[]{""+id});}void toggle(int id,boolean b){ContentValues v=new ContentValues();v.put("done",b?1:0);getWritableDatabase().update("tasks",v,"id=?",new String[]{""+id});}void deleteMission(int id){getWritableDatabase().delete("tasks","mission_id=?",new String[]{""+id});getWritableDatabase().delete("missions","id=?",new String[]{""+id});}String financeHistory(){Cursor c=getReadableDatabase().rawQuery("SELECT date,description,amount,income FROM finance ORDER BY id DESC LIMIT 20",null);StringBuilder s=new StringBuilder();while(c.moveToNext())s.append(c.getString(0)).append("  ").append(c.getInt(3)==1?"+":"-").append(String.format(Locale.US,"%.2f",c.getDouble(2))).append("  ").append(c.getString(1)==null?"":c.getString(1)).append("\n");c.close();return s.length()==0?"Nenhuma movimentação registrada.":s.toString();}String workoutHistory(){Cursor c=getReadableDatabase().rawQuery("SELECT date,push,pull FROM workouts ORDER BY id DESC LIMIT 15",null);StringBuilder s=new StringBuilder();while(c.moveToNext())s.append(c.getString(0)).append("  Flexões: ").append(c.getInt(1)).append("  Barras: ").append(c.getInt(2)).append("\n");c.close();return s.length()==0?"Nenhum treino registrado.":s.toString();}void reset(){for(String t:new String[]{"finance","workouts","missions","tasks"})getWritableDatabase().delete(t,null,null);}}
}
